function drawAetherStorm(){if(!aetherStorm.active)return;ctx.save();ctx.fillStyle='rgba(82,25,116,.24)';ctx.beginPath();ctx.rect(0,0,WORLD.w,WORLD.h);ctx.moveTo(aetherStorm.x+aetherStorm.radius,aetherStorm.y);ctx.arc(aetherStorm.x,aetherStorm.y,aetherStorm.radius,0,Math.PI*2,true);ctx.fill('evenodd');ctx.strokeStyle=`rgba(211,112,255,${.65+.25*Math.sin(time*4)})`;ctx.lineWidth=12;ctx.beginPath();ctx.arc(aetherStorm.x,aetherStorm.y,aetherStorm.radius,0,6.28);ctx.stroke();if(aetherStorm.age>=18){const c=stormCore.cooldown>0?(stormCore.owner==='blue'?'#58ddff':'#ff6072'):'#e0a0ff';ctx.fillStyle=c;ctx.globalAlpha=.3+.2*Math.sin(time*7);ctx.beginPath();ctx.arc(stormCore.x,stormCore.y,stormCore.r,0,6.28);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=c;ctx.lineWidth=5;ctx.beginPath();ctx.arc(stormCore.x,stormCore.y,stormCore.r+Math.sin(time*6)*4,0,6.28);ctx.stroke();if(stormCore.cooldown<=0&&stormCore.progress){ctx.strokeStyle=stormCore.progress>0?'#58ddff':'#ff6072';ctx.lineWidth=8;ctx.beginPath();ctx.arc(stormCore.x,stormCore.y,stormCore.r+10,-Math.PI/2,-Math.PI/2+Math.PI*2*Math.abs(stormCore.progress)/4);ctx.stroke()}}ctx.restore()}
function consumeVitalPlant(p,target){p.dead=true;p.hp=0;p.respawn=45;const max=target.maxHp||100,heal=max*.24;target.hp=Math.min(max,target.hp+heal);if(target===hero){hero.mana=Math.min(hero.maxMana,hero.mana+35);floatText(hero.x,hero.y-42,'+'+Math.round(heal)+' · +35 энергии','#72efa4');showToast('Плод жизни восстановил здоровье и энергию')}else floatText(target.x,target.y-35,'+'+Math.round(heal),'#72efa4');for(let i=0;i<16;i++)particles.push({x:p.x,y:p.y,a:Math.random()*6.28,life:.7,type:'heal'})}
function updatePlants(dt){for(const p of plants){if(p.dead){p.respawn-=dt;if(p.respawn<=0){p.dead=false;p.hp=1;particles.push({x:p.x,y:p.y,life:.8,max:.8,type:'wardPulse'})}continue}if(p.plant!=='vital')continue;if(!hero.dead&&hero.hp/hero.maxHp<.88&&Math.hypot(hero.x-p.x,hero.y-p.y)<38){consumeVitalPlant(p,hero);continue}for(const b of botHeroes)if(!b.dead&&b.hp/b.maxHp<.45&&Math.hypot(b.x-p.x,b.y-p.y)<38){consumeVitalPlant(p,b);break}}}
function convergenceDivision(r=profile.convergenceRating){return r>=1800?'МИФ':r>=1520?'ЛЕГЕНДА':r>=1300?'АЛМАЗ':r>=1120?'ЗОЛОТО':r>=940?'СЕРЕБРО':'БРОНЗА'}
function finishConvergence(win){if(convergence.finished)return;convergence.finished=true;if(gameMode==='convergenceranked'){const expected=1/(1+Math.pow(10,(convergence.opponentRating-profile.convergenceRating)/400)),share=convergence.objectivesBlue-Math.max(0,convergence.objectivesRed),performance=Math.max(-3,Math.min(3,share)),delta=Math.round(30*((win?1:0)-expected))+performance;convergence.ratingDelta=delta;profile.convergenceRating=Math.max(600,profile.convergenceRating+delta);profile.convergencePeakRating=Math.max(profile.convergencePeakRating,profile.convergenceRating);profile.convergenceRankedMatches++;if(win){profile.convergenceRankedWins++;profile.convergenceWinStreak++;profile.convergenceBestStreak=Math.max(profile.convergenceBestStreak,profile.convergenceWinStreak)}else profile.convergenceWinStreak=0;announce(`${win?'ПОБЕДА':'ПОРАЖЕНИЕ'} В ЛИГЕ · ${delta>=0?'+':''}${delta} РЕЙТИНГА`)}setTimeout(()=>endGame(win),600)}
function awardConvergence(team,amount,objective=true){if(convergence.finished)return;const other=team==='blue'?'red':'blue',momentum=convergence[team==='blue'?'momentumBlue':'momentumRed'],trailing=convergence[other]-convergence[team]>=18,mult=objective?(1+momentum*.08)*(trailing?1.2:1)*(convergence.anomaly==='surge'?1.2:1):1,points=amount*mult;convergence[team]+=points;convergence[team==='blue'?'phaseBlue':'phaseRed']+=points;if(convergence.overtime&&points>0){announce(`${team==='blue'?'СИНИЕ':'КРАСНЫЕ'} ЗАВЕРШИЛИ ЗОЛОТУЮ ЦЕЛЬ`);finishConvergence(team==='blue')}}
function settleConvergence(){const b=convergence.phaseBlue,r=convergence.phaseRed;if(b===r)return;if(b>r){convergence.momentumBlue=Math.min(3,convergence.momentumBlue+1);convergence.momentumRed=0;convergence.blue+=3+convergence.momentumBlue*2;convergence.objectivesBlue++}else{convergence.momentumRed=Math.min(3,convergence.momentumRed+1);convergence.momentumBlue=0;convergence.red+=3+convergence.momentumRed*2;convergence.objectivesRed++}announce(`ИМПУЛЬС ЦЕЛИ · ${b>r?'СИНИЕ':'КРАСНЫЕ'} ×${b>r?convergence.momentumBlue:convergence.momentumRed}`)}
function rotateConvergence(){settleConvergence();convergence.phaseBlue=convergence.phaseRed=0;convergence.round++;convergence.rotations++;convergence.objective=['altar','shards','bounty','guardian'][(convergence.round-1)%4];convergence.objectiveTimer=gameMode==='convergenceranked'?35:45;const points=[[1300,900],[930,650],[1680,1140]],p=points[(convergence.round-1)%points.length];convergence.altar={x:p[0],y:p[1]};if(convergence.objective==='shards'){convergence.shards=[[820,620],[1050,1120],[1300,720],[1570,1080],[1830,650]].map((q,i)=>({x:q[0],y:q[1],active:true,value:i===2?12:8}))}const guardian=monsters.find(m=>m.kind==='herald');if(guardian){guardian.dead=true;guardian.respawn=9999}if(convergence.objective==='bounty'){const foes=[enemy,...botHeroes.filter(b=>b.team==='red'&&!b.dead)];convergence.markedBlue=foes[Math.floor(Math.random()*foes.length)]||enemy}if(convergence.objective==='guardian'&&guardian){guardian.dead=false;guardian.rewarded=false;guardian.x=convergence.altar.x;guardian.y=convergence.altar.y;guardian.maxHp=guardian.hp=gameMode==='convergenceranked'?1450:1200;guardian.damage=24;guardian.respawn=9999;convergence.guardianAwarded=false}convergence.anomaly=['surge','tranquil','chaos'][convergence.rotations%3];announce(`КОНВЕРГЕНЦИЯ · ${convergence.objective==='altar'?'УДЕРЖИВАЙТЕ УЗЕЛ':convergence.objective==='shards'?'СОБИРАЙТЕ ПРИЗМЫ':convergence.objective==='bounty'?'УНИЧТОЖЬТЕ МЕТКУ':'СРАЗИТЕ СТРАЖА УЗЛА'}`)}
function updateConvergence(dt){if(gameMode!=='convergence'&&gameMode!=='convergenceranked'||convergence.finished)return;const units=[hero,enemy,...botHeroes];convergence.time=Math.max(0,convergence.time-dt);convergence.objectiveTimer-=dt;if(convergence.objectiveTimer<=0)rotateConvergence();for(const u of units){const down=u.dead||u.hp<=0,marked=convergence.deathMarks.get(u)||false;if(down&&!marked){convergence.deathMarks.set(u,true);const scoring=u.team==='blue'?'red':'blue';awardConvergence(scoring,convergence.anomaly==='chaos'?5:3,false);if(convergence.objective==='bounty'&&((scoring==='blue'&&u===convergence.markedBlue)||(scoring==='red'&&u===hero))){awardConvergence(scoring,15,true);convergence[scoring==='blue'?'objectivesBlue':'objectivesRed']++;announce(`${scoring==='blue'?'СИНИЕ':'КРАСНЫЕ'} ЗАБРАЛИ МЕТКУ · +15`)}}else if(!down&&marked)convergence.deathMarks.set(u,false)}if(convergence.objective==='altar'){const blue=units.filter(u=>u.team==='blue'&&!u.dead&&Math.hypot(u.x-convergence.altar.x,u.y-convergence.altar.y)<175).length,red=units.filter(u=>u.team==='red'&&!u.dead&&Math.hypot(u.x-convergence.altar.x,u.y-convergence.altar.y)<175).length;if(blue>red){awardConvergence('blue',dt*(1+Math.min(2,blue-red)*.35),true);rally.x=convergence.altar.x;rally.y=convergence.altar.y;rally.time=1;rally.type='gather';rally.label='УЗЕЛ КОНВЕРГЕНЦИИ'}else if(red>blue)awardConvergence('red',dt*(1+Math.min(2,red-blue)*.35),true)}else if(convergence.objective==='shards'){for(const s of convergence.shards)if(s.active)for(const u of units)if(!u.dead&&Math.hypot(u.x-s.x,u.y-s.y)<42){s.active=false;awardConvergence(u.team,s.value,true);convergence[u.team==='blue'?'objectivesBlue':'objectivesRed']++;floatText(s.x,s.y-28,`+${s.value} ОЧКОВ`,u.team==='blue'?'#66e6ff':'#ff7185');break}const target=convergence.shards.find(s=>s.active);if(target){rally.x=target.x;rally.y=target.y;rally.time=1;rally.type='gather';rally.label='ПРИЗМА'}}else if(convergence.objective==='bounty'&&convergence.markedBlue&&!convergence.markedBlue.dead){rally.x=convergence.markedBlue.x;rally.y=convergence.markedBlue.y;rally.time=1;rally.type='attack';rally.target=convergence.markedBlue;rally.label='МЕТКА'}else if(convergence.objective==='guardian'){const guardian=monsters.find(m=>m.kind==='herald');if(guardian){if((guardian.dead||guardian.hp<=0)&&!convergence.guardianAwarded){convergence.guardianAwarded=true;const blue=units.filter(u=>u.team==='blue'&&!u.dead&&Math.hypot(u.x-guardian.x,u.y-guardian.y)<420).length,red=units.filter(u=>u.team==='red'&&!u.dead&&Math.hypot(u.x-guardian.x,u.y-guardian.y)<420).length,team=blue===red?(convergence.blue<=convergence.red?'blue':'red'):blue>red?'blue':'red';awardConvergence(team,20,true);convergence[team==='blue'?'guardiansBlue':'guardiansRed']++;convergence[team==='blue'?'objectivesBlue':'objectivesRed']++;announce(`${team==='blue'?'СИНИЕ':'КРАСНЫЕ'} ПОКОРИЛИ СТРАЖА · +20`)}else{rally.x=guardian.x;rally.y=guardian.y;rally.time=1;rally.type='attack';rally.target=guardian;rally.label='СТРАЖ УЗЛА'}}}const redTarget=convergence.objective==='altar'?convergence.altar:convergence.objective==='shards'?convergence.shards.find(s=>s.active):convergence.objective==='guardian'?monsters.find(m=>m.kind==='herald'&&!m.dead):hero;if(redTarget&&convergence.anomaly==='tranquil')for(const u of units)if(!u.dead&&Math.hypot(u.x-redTarget.x,u.y-redTarget.y)<220)u.hp=Math.min(u.maxHp,u.hp+u.maxHp*.012*dt);if(redTarget)for(const b of [enemy,...botHeroes.filter(x=>x.team==='red')])if(!b.dead&&Math.hypot(b.x-redTarget.x,b.y-redTarget.y)<950){steerUnit(b,redTarget,65,dt)}if(convergence.blue>=convergence.target||convergence.red>=convergence.target){finishConvergence(convergence.blue>=convergence.red)}else if(convergence.time<=0&&!convergence.overtime){if(Math.floor(convergence.blue)===Math.floor(convergence.red)){convergence.overtime=true;convergence.objectiveTimer=999;convergence.overtimeStartBlue=convergence.blue;convergence.overtimeStartRed=convergence.red;announce('ЗОЛОТАЯ ЦЕЛЬ · СЛЕДУЮЩИЕ ОЧКИ РЕШАЮТ')}else{finishConvergence(convergence.blue>convergence.red)}}}
function drawConvergence(){if(gameMode!=='convergence'&&gameMode!=='convergenceranked')return;if(convergence.objective==='altar'){ctx.fillStyle='#ff7de322';ctx.strokeStyle='#ff7de3';ctx.lineWidth=8;ctx.beginPath();ctx.arc(convergence.altar.x,convergence.altar.y,175,0,6.28);ctx.fill();ctx.stroke();ctx.fillStyle='#fff';ctx.font='900 13px system-ui';ctx.textAlign='center';ctx.fillText('УЗЕЛ КОНВЕРГЕНЦИИ',convergence.altar.x,convergence.altar.y+5)}else if(convergence.objective==='shards')for(const s of convergence.shards)if(s.active){ctx.save();ctx.translate(s.x,s.y);ctx.rotate(time*2);ctx.fillStyle=s.value>8?'#fff08a':'#ff8be5';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=20;ctx.beginPath();ctx.moveTo(0,-19);ctx.lineTo(14,0);ctx.lineTo(0,19);ctx.lineTo(-14,0);ctx.closePath();ctx.fill();ctx.restore()}else if(convergence.objective==='bounty'&&convergence.markedBlue&&!convergence.markedBlue.dead){const u=convergence.markedBlue;ctx.strokeStyle='#ffe05f';ctx.lineWidth=6;ctx.beginPath();ctx.arc(u.x,u.y,44+Math.sin(time*6)*5,0,6.28);ctx.stroke();ctx.fillStyle='#ffe05f';ctx.font='900 11px system-ui';ctx.textAlign='center';ctx.fillText('МЕТКА',u.x,u.y-54)}else if(convergence.objective==='guardian'){const g=monsters.find(m=>m.kind==='herald');if(g&&!g.dead){ctx.strokeStyle='#ff8ce8';ctx.lineWidth=8;ctx.beginPath();ctx.arc(g.x,g.y,115+Math.sin(time*4)*6,0,6.28);ctx.stroke();ctx.fillStyle='#fff0a0';ctx.font='900 12px system-ui';ctx.textAlign='center';ctx.fillText('СТРАЖ УЗЛА · 20 ОЧКОВ',g.x,g.y-128)}}}
function resetRuneSeals(){const points=[[870,660],[1320,1240],[1770,660]];runeTrial.seals=points.map((p,i)=>({x:p[0],y:p[1],progress:0,active:true,id:['force','spirit','time'][i],name:['ПЕЧАТЬ СИЛЫ','ПЕЧАТЬ ДУХА','ПЕЧАТЬ ВРЕМЕНИ'][i]}));runeTrial.sealsBroken=0}
function updateRuneTrial(dt){if(gameMode!=='runetrial'||runeTrial.finished)return;const titan=monsters.find(m=>m.kind==='titan'),allies=[hero,...botHeroes.filter(b=>b.team==='blue')];runeTrial.time=Math.max(0,runeTrial.time-dt);if(hero.dead||hero.hp<=0)runeTrial.perfect=false;if(!titan)return;if((titan.dead||titan.hp<=0)&&runeTrial.phaseTransitions<2){titan.dead=false;titan.rewarded=false;titan.hp=titan.maxHp*(runeTrial.phaseTransitions===0?.7:.35);titan.respawn=9999}runeTrial.hazardCd-=dt;if(runeTrial.hazardCd<=0&&!titan.dead){const cd=runeTrial.phase===3?5:runeTrial.phase===2?7:9;runeTrial.hazardCd=cd;if(runeTrial.phase===1){for(const u of allies)if(!u.dead&&Math.hypot(u.x-titan.x,u.y-titan.y)<390){const dmg=24;if(u===hero)hurtHero(dmg,false,'Рунический импульс');else u.hp=Math.max(1,u.hp-dmg)}particles.push({x:titan.x,y:titan.y,life:1,max:1,type:'enemyNova'});announce('СТРАЖ · РУНИЧЕСКИЙ ИМПУЛЬС')}else{createDangerZone(hero.x,hero.y,runeTrial.phase===3?125:95,runeTrial.phase===3?.65:.9,runeTrial.phase===3?48:34,'Кара печатей','slow',runeTrial.phase===3?'#ff536e':'#ffd45f');if(runeTrial.phase===3){const target=allies.filter(u=>u!==hero&&!u.dead)[Math.floor(Math.random()*Math.max(1,allies.filter(u=>u!==hero&&!u.dead).length))];if(target)target.hp=Math.max(1,target.hp-32)}}}const ratio=titan.hp/titan.maxHp,nextPhase=runeTrial.phaseTransitions===0&&ratio<=.7?2:runeTrial.phaseTransitions===1&&ratio<=.35?3:0;if(nextPhase&&!titan.dead){runeTrial.phase=nextPhase;runeTrial.phaseTransitions++;runeTrial.shielded=true;runeTrial.shieldHp=titan.hp;runeTrial.vulnerable=0;resetRuneSeals();runeTrial.hazardCd=4;if(nextPhase===3){titan.damage=Math.round(titan.damage*1.3);titan.slamCd=Math.max(1.2,titan.slamCd*.7)}announce(`СТРАЖ ПЕРЕШЁЛ В ФАЗУ ${nextPhase} · ЩИТ ВОССТАНОВЛЕН`)}if(runeTrial.shielded&&!titan.dead)titan.hp=Math.max(titan.hp,runeTrial.shieldHp);for(const seal of runeTrial.seals){if(!seal.active)continue;const nearby=allies.filter(u=>!u.dead&&u.hp>0&&Math.hypot(u.x-seal.x,u.y-seal.y)<105).length;if(nearby)seal.progress=Math.min(4,seal.progress+dt*(1+nearby*.35));else seal.progress=Math.max(0,seal.progress-dt*.45);if(seal.progress>=4){seal.active=false;runeTrial.sealsBroken++;runeTrial.dustEarned+=10;if(seal.id==='force'){runeTrial.forceStacks++;for(const u of allies)u.damage=Math.round(u.damage*1.03)}else if(seal.id==='spirit')for(const u of allies)if(!u.dead)u.hp=Math.min(u.maxHp,u.hp+u.maxHp*.22);else if(seal.id==='time'){for(const k of ['Q','W','E','R'])hero.cd[k]=Math.max(0,hero.cd[k]*.65);for(const b of botHeroes.filter(x=>x.team==='blue')){b.abilityCd=Math.max(0,(b.abilityCd||0)*.6);b.ultCd=Math.max(0,(b.ultCd||0)*.7)}}floatText(seal.x,seal.y-35,seal.id==='force'?'МОЩЬ +3%':seal.id==='spirit'?'ИСЦЕЛЕНИЕ 22%':'ВРЕМЯ УСКОРЕНО','#ffe06b');particles.push({x:seal.x,y:seal.y,life:1,max:1,type:'nova'});sfx('win')}}if(runeTrial.shielded&&runeTrial.sealsBroken>=3){runeTrial.shielded=false;runeTrial.vulnerable=35;runeTrial.cycles++;announce('ЩИТ СТРАЖА РАЗРУШЕН · 35 СЕКУНД');rally.x=titan.x;rally.y=titan.y;rally.type='attack';rally.target=titan;rally.label='АТАКОВАТЬ СТРАЖА';rally.time=35}if(!runeTrial.shielded){runeTrial.vulnerable-=dt;if(runeTrial.vulnerable<=0&&!titan.dead&&titan.hp>0){runeTrial.shielded=true;runeTrial.shieldHp=titan.hp;resetRuneSeals();announce(`СТРАЖ ВОССТАНОВИЛ ЩИТ · НОВЫЙ ЦИКЛ`)}}else{const target=runeTrial.seals.find(s=>s.active);if(target){rally.x=target.x;rally.y=target.y;rally.type='gather';rally.target=null;rally.label=target.name;rally.time=2}}if(titan.dead||titan.hp<=0){runeTrial.finished=true;runeTrial.dustEarned+=runeTrial.perfect?40:20;profile.runeDust+=runeTrial.dustEarned;const cores=runeTrial.perfect?2:1;profile.runeCores+=cores;announce(`ИСПЫТАНИЕ ЗАВЕРШЕНО · +${runeTrial.dustEarned} ✧ · +${cores} ◆`);setTimeout(()=>endGame(true),700)}else if(runeTrial.time<=0){runeTrial.finished=true;profile.runeDust+=runeTrial.dustEarned;announce(`ВРЕМЯ ИСТЕКЛО · СОБРАНО ${runeTrial.dustEarned} ✧`);setTimeout(()=>endGame(false),700)}}
function drawRuneTrial(){if(gameMode!=='runetrial')return;const titan=monsters.find(m=>m.kind==='titan');for(const seal of runeTrial.seals){ctx.fillStyle=seal.active?'#ffd55f22':'#65e6ff18';ctx.strokeStyle=seal.active?'#ffd55f':'#65e6ff';ctx.lineWidth=5;ctx.beginPath();ctx.arc(seal.x,seal.y,74,0,6.28);ctx.fill();ctx.stroke();if(seal.active){ctx.strokeStyle='#fff1a0';ctx.lineWidth=8;ctx.beginPath();ctx.arc(seal.x,seal.y,86,-Math.PI/2,-Math.PI/2+Math.PI*2*seal.progress/4);ctx.stroke()}ctx.fillStyle=ctx.strokeStyle;ctx.font='900 10px system-ui';ctx.textAlign='center';ctx.fillText(seal.active?seal.name:'РАЗРУШЕНА',seal.x,seal.y+4)}if(titan&&runeTrial.shielded&&!titan.dead){ctx.strokeStyle=runeTrial.phase===3?'#ff5575':runeTrial.phase===2?'#d86cff':'#ffe276';ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=24;ctx.lineWidth=12;ctx.beginPath();ctx.arc(titan.x,titan.y,96+Math.sin(time*5)*5,0,6.28);ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#ffe276';ctx.font='900 12px system-ui';ctx.textAlign='center';ctx.fillText(`ЩИТ · ${runeTrial.sealsBroken}/3`,titan.x,titan.y-112)}}
function eclipseDivision(r=profile.eclipseRating){return r>=1750?'МИФ':r>=1500?'ЛЕГЕНДА':r>=1280?'АЛМАЗ':r>=1100?'ЗОЛОТО':r>=930?'СЕРЕБРО':'БРОНЗА'}
function finishEclipse(win){if(eclipse.finished)return;eclipse.finished=true;if(gameMode==='eclipseranked'){const expected=1/(1+Math.pow(10,(eclipse.opponentRating-profile.eclipseRating)/400)),delta=Math.round(32*((win?1:0)-expected));eclipse.ratingDelta=delta;profile.eclipseRating=Math.max(600,profile.eclipseRating+delta);profile.eclipsePeakRating=Math.max(profile.eclipsePeakRating,profile.eclipseRating);profile.eclipseRankedMatches++;if(win){profile.eclipseRankedWins++;profile.eclipseWinStreak++;profile.eclipseBestStreak=Math.max(profile.eclipseBestStreak,profile.eclipseWinStreak)}else profile.eclipseWinStreak=0;announce(`${win?'ПОБЕДА':'ПОРАЖЕНИЕ'} В ЛИГЕ · ${delta>=0?'+':''}${delta} РЕЙТИНГА`)}setTimeout(()=>endGame(win),650)}
