function riftballDivision(r=profile.riftballRating){return r>=1700?'МИФ':r>=1450?'ЛЕГЕНДА':r>=1250?'АЛМАЗ':r>=1100?'ЗОЛОТО':r>=950?'СЕРЕБРО':'БРОНЗА'}
function resetRiftball(){riftball.x=1300;riftball.y=900;riftball.vx=riftball.vy=0;riftball.reset=2.2;riftball.lastTouch=null}
